<?php require '../includes/bootstrap.php';student_required();$s=$pdo->prepare("SELECT h.*,op.problem_code old_code,np.problem_code new_code FROM selection_history h LEFT JOIN problem_statements op ON op.problem_id=h.old_problem_id LEFT JOIN problem_statements np ON np.problem_id=h.new_problem_id WHERE h.student_id=? ORDER BY h.action_time DESC");$s->execute([$_SESSION['student_id']]);$rows=$s->fetchAll();$title='Selection History';$base='../';$nav='<a href="dashboard.php">Dashboard</a><a href="problems.php">Problems</a><a href="team.php">Team</a><a href="../logout.php">Logout</a>';include '../includes/header.php';?><h1>Selection History</h1><div class="card"><table class="table"><tr><th>Action</th><th>Old</th><th>New</th><th>Time</th><th>Notes</th></tr><?php foreach($rows as $r):?><tr><td><span class="badge"><?=e($r['action_type'])?></span></td><td><?=e($r['old_code']?:'—')?></td><td><?=e($r['new_code']?:'—')?></td><td><?=e($r['action_time'])?></td><td><?=e($r['notes'])?></td></tr><?php endforeach;?></table></div><?php include '../includes/footer.php';?>
